import java.nio.ByteBuffer;
import java.nio.file.Files;
import java.nio.file.Path;
import java.security.MessageDigest;

public class MistSpan {
    static final int ALIGN = 32;
    static final int PIN = 48;

    public static byte[] tint_k(Path silo, byte[] wanted) throws Exception {
        if (wanted == null || wanted.length != 16) return null;
        byte[] pins = read(silo.resolve("pin.bin"));
        byte[] blob = read(silo.resolve("blob.bin"));
        for (int pos = 0; pos + PIN <= pins.length; pos += PIN) {
            ByteBuffer p = ByteBuffer.wrap(pins, pos, PIN);
            byte[] magic = new byte[4]; p.get(magic);
            long off = p.getLong();
            int len = p.getInt();
            int crc = p.getInt();
            byte[] id = new byte[16]; p.get(id);
            if (!same(id, wanted)) continue;
            if (!magic(magic) || off < 0 || len < 0 || off > Integer.MAX_VALUE) return null;
            long rec = 4L + len;
            long padded = rec + ((ALIGN - (rec % ALIGN)) % ALIGN);
            if (padded > Integer.MAX_VALUE || off > blob.length || padded > blob.length - off) return null;
            int at = (int)off;
            if (ByteBuffer.wrap(blob, at, 4).getInt() != len) return null;
            byte[] body = new byte[len];
            System.arraycopy(blob, at + 4, body, 0, len);
            if (Crc.of(body) != crc || !same(firstId(body), id)) return null;
            return body;
        }
        return null;
    }

    static byte[] read(Path p) throws Exception {
        return Files.exists(p) ? Files.readAllBytes(p) : new byte[0];
    }
    static boolean magic(byte[] m) {
        return m.length == 4 && m[0]=='P' && m[1]=='N' && m[2]=='0' && m[3]=='1';
    }
    static byte[] firstId(byte[] body) throws Exception {
        byte[] d = MessageDigest.getInstance("SHA-256").digest(body);
        byte[] id = new byte[16]; System.arraycopy(d, 0, id, 0, 16); return id;
    }
    static boolean same(byte[] x, byte[] y) {
        if (x == null || y == null || x.length != y.length) return false;
        for (int i=0; i<x.length; i++) if (x[i] != y[i]) return false;
        return true;
    }
}
